import { defaultNetwork, defaultReality, defaultSettings, defaultSniffing, newClient, randStr, type InboundProtocol, type Obj } from './xray'

// The configs of pdnczone/3x-ui-pro-configs that need no certificate or
// Cloudflare, as shared-template inbounds. The TLS, CDN and Hysteria2 ones
// live in the CDN add-on (addonPresets), whose servers have both names.
// Ports follow the script's preferences; the first free one is taken.
// Reality keys and the VLESS Encryption pair ("vlessenc") are generated by
// the backend once, so every server gets the same ones.

export interface ProPreset {
  key: string
  title: string
  note: string
  /** Candidate ports, best first. */
  ports: number[]
  build: () => { protocol: InboundProtocol; settings: Obj; stream: Obj }
}

const hex = '0123456789abcdef'
const path = () => '/' + randStr(10)
const vlessWith = (flow = '') => ({ ...defaultSettings('vless'), clients: [{ ...newClient('vless'), flow }] })
const tcp = () => defaultNetwork('tcp')

function reality(network: string, target: string, extra: Obj): Obj {
  return { network, security: 'reality', ...extra, realitySettings: { ...defaultReality(), target: `${target}:443`, serverNames: [target] } }
}

const xhttp = () => ({ xhttpSettings: { ...defaultNetwork('xhttp').xhttpSettings, path: path() } })

export const proPresets: ProPreset[] = [
  {
    key: 'rv', title: '⚡ Reality Vision', note: 'سریع‌ترین و مخفی‌ترین؛ کانفیگ اصلی', ports: [443, 2443, 3443, 6443, 7443],
    build: () => ({ protocol: 'vless', settings: vlessWith('xtls-rprx-vision'), stream: reality('tcp', 'dl.google.com', tcp()) }),
  },
  {
    key: 'rx', title: '🌀 Reality XHTTP', note: 'REALITY روی XHTTP با padding', ports: [8443, 2443, 3443, 5443, 6443],
    build: () => ({ protocol: 'vless', settings: vlessWith(), stream: reality('xhttp', 'addons.mozilla.org', xhttp()) }),
  },
  {
    key: 'rg', title: '🔷 Reality gRPC', note: 'REALITY روی gRPC (multiMode)', ports: [4443, 5443, 7443, 9444],
    build: () => ({
      protocol: 'vless', settings: vlessWith(),
      stream: reality('grpc', 'www.samsung.com', { grpcSettings: { serviceName: randStr(8, hex), authority: '', multiMode: true } }),
    }),
  },
  {
    key: 'pq', title: '🧬 PQ Sudoku', note: 'VLESS پست‌کوانتومی + Sudoku (آزمایشی، کلاینت Xray 26)', ports: [10443, 11443, 12443, 13443],
    build: () => ({
      protocol: 'vless', settings: { ...vlessWith(), decryption: 'vlessenc', encryption: '' },
      stream: {
        network: 'tcp', security: 'none', ...tcp(),
        finalmask: { tcp: [{ type: 'sudoku', settings: { password: randStr(32, hex), ascii: 'prefer_entropy', paddingMin: 2, paddingMax: 7 } }] },
      },
    }),
  },
  {
    key: 'ss', title: '🛟 Shadowsocks-2022', note: 'پشتیبان ساده', ports: [8080, 8388, 18080, 28080],
    build: () => {
      const settings = defaultSettings('shadowsocks')
      return { protocol: 'shadowsocks', settings: { ...settings, clients: [newClient('shadowsocks', settings.method)] }, stream: { network: 'tcp', security: 'none', ...tcp() } }
    },
  },
]

/** The first preferred port the template does not use yet. */
export function proPort(p: ProPreset, used: number[]): number | undefined {
  return p.ports.find((x) => !used.includes(x))
}

/** The body of a new template inbound built from p on port. */
export function proInbound(p: ProPreset, port: number) {
  const b = p.build()
  return {
    remark: p.title.replace(/^\S+\s/, '').replace(/ · /g, ' '),
    protocol: b.protocol, port, enabled: true, upload: true, upload_json: false, cdn: false,
    settings: JSON.stringify(b.settings), stream_settings: JSON.stringify(b.stream),
    sniffing: JSON.stringify({ ...defaultSniffing, routeOnly: true }),
  }
}
